verification_commands.ac1:
set -u
test -f README.md || { echo "ac1 RED: README.md missing - run the fence from the checkout root"; exit 1; }
command -v python3 >/dev/null || { echo "ac1 RED: python3 missing - the generator-counter rehearsal and the position control are the load-bearing legs of this fence"; exit 1; }
T=$(tr -d '\r' < README.md)
H=$(printf "%s\n" "$T" | grep -cE "^## ")
[ "$H" = "18" ] || { echo "ac1 RED: README carries $H level-2 headings, not 18 - Part 2 adds exactly ONE level-2 section to the 17 it inherits, renames none and removes none (leg 256's stored 17 is amended by the orchestrator from this card's written proposal, never by editing the README down to fit it)"; exit 1; }
[ "$(printf "%s\n" "$T" | grep -cE '^## Reviewer / agent scoring map[[:space:]]*$')" = "1" ] || { echo "ac1 RED: there is not exactly one '## Reviewer / agent scoring map' heading - the operator asked for one Part 2, not a duplicate or a near-miss title"; exit 1; }
LN=$(printf "%s\n" "$T" | grep -nE '^## Reviewer / agent scoring map[[:space:]]*$' | cut -d: -f1)
SH=$(printf "%s\n" "$T" | grep -nE '^## Screenshots[[:space:]]*$' | cut -d: -f1)
CM=$(printf "%s\n" "$T" | grep -nE '^## Criteria mapping[[:space:]]*$' | cut -d: -f1)
EC=$(printf "%s\n" "$T" | grep -nE '^## Evidence checklist[[:space:]]*$' | cut -d: -f1)
DR=$(printf "%s\n" "$T" | grep -nE '^## Deployment on Render[[:space:]]*$' | cut -d: -f1)
[ -n "$SH" ] && [ -n "$CM" ] && [ -n "$EC" ] && [ -n "$DR" ] || { echo "ac1 RED: one of the carried anchor sections (Screenshots / Criteria mapping / Evidence checklist / Deployment on Render) is gone - Part 2 is ADDED, the 17 inherited sections stay"; exit 1; }
{ [ "$LN" -gt "$SH" ] && [ "$LN" -lt "$CM" ]; } || { echo "ac1 RED: the new section sits at line $LN, not between ## Screenshots ($SH) and ## Criteria mapping ($CM) - the position is load-bearing: docs_verification.py counts the Chapter 24.3 rows as text.split('## Criteria mapping')[1].split('## Evidence checklist')[0], so ANY numbered row placed between those two headings is counted as a criteria row (15 + 12 = 27, not 15), the generator goes RED, and legs 256/257/258/259 which run or re-attest it go RED with it. The survey's window (after Criteria mapping, before Evidence checklist) is falsified by that measurement"; exit 1; }
[ "$LN" -lt "$DR" ] || { echo "ac1 RED: the new section is placed after ## Deployment on Render, i.e. inside the tail leg 255 (t70 ac3) scans to end-of-file - that leg forbids any URL outside localhost and the -1qtu host and bans internal-pipeline vocabulary in that range, so a trailing Part 2 would trip a gate that was never meant to read a scoring map"; exit 1; }
echo "ac1 evidence: the section is at line $LN, between ## Screenshots ($SH) and ## Criteria mapping ($CM), and clear of the leg-255 tail at $DR"
SEC=$(printf "%s\n" "$T" | sed -n "/^## Reviewer \/ agent scoring map/,/^## /p")
printf "%s\n" "$SEC" | grep -qiE "not the (chapter )?24[.]3|distinct from|separate from|24[.]3" || { echo "ac1 RED: the section never distinguishes itself from the Chapter 24.3 criteria-mapping table - a grader who finds two similar tables must be told which is which, or the map defeats its own purpose"; exit 1; }
printf "%s\n" "$SEC" | grep -qiE "24[.]5|evidence checklist" || { echo "ac1 RED: the section never distinguishes itself from the Chapter 24.5 evidence checklist - same reason"; exit 1; }
printf "%s\n" "$SEC" | grep -qiE "30 second|30-second" || { echo "ac1 RED: the section never states the 30-second contract that its own entry points are built to satisfy"; exit 1; }
python3 - <<'PYEOF' || exit 1
import re, sys
readme = open("README.md", encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
gen = open("backend/scripts/docs_verification.py", encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
if not re.search(r"split\([\"']## Criteria mapping[\"'], ?1\)\[1\]\.split\([\"']## Evidence checklist", gen):
    sys.stderr.write("ac1 RED: docs_verification.py no longer counts the 24.3 rows with the split-based leg this card's position was designed around - STOP and request a re-groom rather than guessing a position\n"); raise SystemExit(1)

def counters(text):
    crit = re.findall(r"^\|\s*\d+\s*\|", text.split("## Criteria mapping", 1)[1].split("## Evidence checklist", 1)[0], re.M)
    chk = re.findall(r"^\|\s*\d+\s*\|", text.split("## Evidence checklist", 1)[1].split("## ", 1)[0], re.M)
    five = re.findall(r"^#{2,3}.*(five|5)[ -]minute", text, re.M | re.I)
    return len(crit), len(chk), len(five)

c0, c1, c2 = counters(readme)
h2 = len(re.findall(r"^## ", readme, re.M))
fail = []
if c0 != 15:
    fail.append("CRITERIA243_ROWS would be %d, want 15 - the twelve Part-2 rows are being counted inside the 24.3 range, which is exactly what the pre-Criteria-mapping position prevents" % c0)
if c1 != 14:
    fail.append("EVIDENCE_CHECKLIST would be %d, want 14 - the section was inserted inside the checklist range and truncated it" % c1)
if c2 != 2:
    fail.append("FIVE_MIN_PATHS would be %d, want 2" % c2)
if h2 != 18:
    fail.append("level-2 headings = %d, want 18" % h2)
if fail:
    sys.stderr.write("ac1 RED: the generator's own counters disagree with the candidate:\n" + "".join("  - " + f + "\n" for f in fail)); raise SystemExit(1)
sys.stdout.write("ac1 evidence: generator rehearsal on the candidate bytes - CRITERIA243_ROWS 15, EVIDENCE_CHECKLIST 14, FIVE_MIN_PATHS 2, 18 level-2 headings\n")
# NEGATIVE CONTROL: the same twelve-row table placed in the SURVEY window must be refused by
# BOTH the position leg (its heading lands after ## Criteria mapping) and the split-based counter.
synth = ["## Reviewer / agent scoring map", "", "not 24.3, not 24.5, 30-second contract", "",
         "| # | Dimension (max points) | Claim | Why | First entry point | Deep dive |",
         "|---|---|---|---|---|---|"] + [
         "| %d | Dimension %d (0-2) | 2/2 | x | `README.md` | `y` |" % (i, i) for i in range(1, 13)] + [""]
block = "\n".join(synth) + "\n"
# strip the real Part-2 section out first, so the control tests POSITION, not duplication
real = re.search(r"^## Reviewer / agent scoring map.*?(?=^## )", readme, re.S | re.M)
if not real:
    sys.stderr.write("ac1 RED: NEGATIVE CONTROL could not locate the Part-2 section to relocate\n"); raise SystemExit(1)
stripped = readme[:real.start()] + readme[real.end():]
if counters(stripped)[0] != 15:
    sys.stderr.write("ac1 RED: NEGATIVE CONTROL is not clean - the README without Part 2 does not count 15 criteria rows, so the control would prove nothing\n"); raise SystemExit(1)
tail_at = stripped.index("## Evidence checklist")
moved = stripped[:tail_at] + block + stripped[tail_at:]
m0, m1, m2 = counters(moved)
mln = moved.index("## Reviewer / agent scoring map")
mcm = moved.index("## Criteria mapping")
refused = 0
if m0 != 15:
    refused += 1
if not (mln < mcm):
    refused += 1
if refused != 2:
    sys.stderr.write("ac1 RED: NEGATIVE CONTROL FAILED (%d of 2) - the same table inside the survey window counted %d criteria rows and placed the heading %s ## Criteria mapping; BOTH the position leg and the split-based 24.3 counter must refuse that layout or one of them is vacuous\n" % (refused, m0, "before" if mln < mcm else "after")); raise SystemExit(1)
sys.stdout.write("ac1 evidence: NEGATIVE CONTROL - the same table inside the survey window counts %d criteria rows (want 15) with its heading after ## Criteria mapping, so both load-bearing legs bite\n" % m0)
PYEOF
echo "ac1 GREEN: PART 2 EXISTS ONCE IN THE ONLY SAFE PLACE - 18 level-2 headings, the section between ## Screenshots and ## Criteria mapping and clear of the leg-255 tail, distinguishing itself from both the 24.3 and 24.5 tables and stating the 30-second contract; the generator's own 15/14/2 counters rehearse GREEN on the candidate and the survey window is refused by both the position leg and the 27-row counter (negative control 2/2)"

verification_commands.ac3:
set -u
test -f README.md || { echo "ac3 RED: README.md missing"; exit 1; }
for f in process app delivery telemetry; do
  test -f "docs/criteria/scoring_map/$f.md" || { echo "ac3 RED: docs/criteria/scoring_map/$f.md missing - Part 2's claims are copied from those four records and traceability to a record that does not exist is not traceability"; exit 1; }
done
command -v python3 >/dev/null || { echo "ac3 RED: python3 missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import os, re, sys
readme = open("README.md", encoding="utf-8", errors="replace").read().replace("\r", "")
m = re.search(r"^## Reviewer / agent scoring map[ \t]*$(.*?)(?=^## |\Z)", readme, re.M | re.S)
if not m:
    sys.stderr.write("ac3 RED: no Part 2 section\n"); raise SystemExit(1)
sec = m.group(1)
rows = {}
for r in re.finditer(r"^\|\s*(\d+)\s*\|.*\|\s*$", sec, re.M):
    cells = [x.strip() for x in r.group(0).split("|")]
    # cells[0] and cells[-1] are the outer empties of a well-formed row
    if len(cells) != 8:
        sys.stderr.write("ac3 RED: row %s has %d cells, not the six the agreed column contract defines - the deep-dive and reason cells must contain no raw pipe\n" % (r.group(1), len(cells) - 2)); raise SystemExit(1)
    rows[int(r.group(1))] = {"dim": cells[2], "claim": cells[3], "why": cells[4], "entry": cells[5], "deep": cells[6]}
if len(rows) != 12 or set(rows) != set(range(1, 13)):
    sys.stderr.write("ac3 RED: %d parsable numbered rows, not the twelve expected\n" % len(rows)); raise SystemExit(1)
# parse the four measurement records: dimension -> claim / first entry point / every backticked path
rec = {}
for tag in ("process", "app", "delivery", "telemetry"):
    p = "docs/criteria/scoring_map/%s.md" % tag
    body = open(p, encoding="utf-8", errors="replace").read().replace("\r", "")
    for d in re.finditer(r"^## (.+?)\s*$(.*?)(?=^## |\Z)", body, re.M | re.S):
        name, chunk = d.group(1).strip(), d.group(2)
        cl = re.search(r"^- Claim:\s*([0-9]+/[0-9]+)", chunk, re.M)
        ep = re.search(r"^- First entry point:\s*`([^`]+)`", chunk, re.M)
        paths = set(re.findall(r"`([^`]+)`", chunk))
        if not cl or not ep:
            sys.stderr.write("ac3 RED: record dimension '%s' in %s carries no Claim or First entry point line - the record itself is malformed and cannot certify anything\n" % (name, p)); raise SystemExit(1)
        rec[name] = {"claim": cl.group(1), "ep": ep.group(1), "paths": paths, "file": p, "chunk": chunk}
bad = []
for n in range(1, 13):
    dim = re.sub(r"\s*\(?0-?\d+\)?\s*$", "", rows[n]["dim"]).strip()
    if dim not in rec:
        bad.append("row%d names dimension '%s' which NO record defines" % (n, dim)); continue
    R = rec[dim]
    if rows[n]["claim"] != R["claim"]:
        bad.append("row%d claims %s, record '%s' measured %s - no number in this table is this card's to invent or inflate" % (n, rows[n]["claim"], dim, R["claim"]))
    if rows[n]["entry"].strip("`") != R["ep"]:
        bad.append("row%d entry point '%s' is not the record's First entry point '%s' for '%s' - the 30-second promise is the record's, not a pointer the card picked for looks" % (n, rows[n]["entry"], R["ep"], dim))
    deep = re.findall(r"`([^`]+)`", rows[n]["deep"])
    if not deep:
        bad.append("row%d deep-dive cell carries no backticked path" % n); continue
    miss = [t for t in deep if t not in R["paths"] and not os.path.exists(t)]
    if miss:
        bad.append("row%d deep-dive path(s) %s appear in no record and not on the tree - deep dives must name the record and its artifact" % (n, miss))
if bad:
    sys.stderr.write("ac3 RED: " + "; ".join(bad) + "\n"); raise SystemExit(1)
# the CI/CD row is the priced gap, in the README and traceable to the delivery record
c9 = rows[9]
if c9["claim"] != "2/3":
    sys.stderr.write("ac3 RED: the CI/CD row claims %s, not the records' 2/3 - the third point is NOT fully met and the row that hides the gap is the row the operator reads first\n" % c9["claim"]); raise SystemExit(1)
if "promote.yml" not in c9["why"] or "production" not in c9["why"].lower():
    sys.stderr.write("ac3 RED: the CI/CD row does not carry the priced-gap pointers (.github/workflows/promote.yml and the production Environment) that the t114 record's Gap line names\n"); raise SystemExit(1)
if "Gap:" not in rec["CI/CD"]["chunk"]:
    sys.stderr.write("ac3 RED: the delivery record lost its Gap line - the README row's honesty is anchored there\n"); raise SystemExit(1)
# NEGATIVE CONTROLS: the same legs must refuse (a) an inflated claim and (b) a swapped entry point
if "2/3" == rec["CI/CD"]["claim"] and "3/3" != rec["CI/CD"]["claim"]:
    pass
else:
    sys.stderr.write("ac3 RED: NEGATIVE CONTROL FAILED - the record comparison is not discriminating\n"); raise SystemExit(1)
for probe, want in (("Observability", "1/2"), ("Alerting on User Impact", "1/1")):
    if rec[probe]["claim"] != want:
        sys.stderr.write("ac3 RED: NEGATIVE CONTROL ground truth moved - %s record now claims %s not %s; re-groom\n" % (probe, rec[probe]["claim"], want)); raise SystemExit(1)
# a synthetic inflated row and a synthetic swapped entry point, run through the SAME comparison
def refuses(dim, claim, ep):
    R = rec[dim]
    return claim != R["claim"] or ep != R["ep"]
if not refuses("Observability", "2/2", rec["Observability"]["ep"]):
    sys.stderr.write("ac3 RED: NEGATIVE CONTROL FAILED - an inflated 2/2 claim on Observability (record: 1/2) was NOT refused; the claim leg is inert\n"); raise SystemExit(1)
if not refuses("Testing", rec["Testing"]["claim"], "package.json"):
    sys.stderr.write("ac3 RED: NEGATIVE CONTROL FAILED - Testing pointing at package.json (record: Makefile) was NOT refused; the entry-point leg is inert\n"); raise SystemExit(1)
sys.stdout.write("ac3 evidence: all twelve rows' claims EQUAL their record's measured claim, all twelve entry points EQUAL their record's First entry point line, every deep-dive path appears in its record; the CI/CD row is 2/3 with the promote.yml/production pointers and the record's Gap line stands; negative controls refused: an inflated Observability 2/2 and a Testing row pointing at package.json instead of Makefile\n")
PYEOF
echo "ac3 GREEN: TRACEABILITY BY STRING COMPARISON - every claim, entry point and deep dive in the twelve rows equals what the t112-t115 records measured (the honesty rule enforced by comparison, not intention), the CI/CD row is the priced 2/3 with its promote.yml and production-environment pointers, and claim-inflation and entry-point-swap are both refused by the same legs"

verification_commands.ac4:
set -u
test -f docs/state/merge_test_index.json || { echo "ac4 RED: docs/state/merge_test_index.json missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac4 RED: python3 missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import hashlib, json, os, sys
A = "docs/state/outputs/t116_definer_gate_amendment.json"
if not os.path.exists(A):
    sys.stderr.write("ac4 RED: %s missing - adding an 18th level-2 section and past-400 lines breaks legs 256 and 258, and a card that breaks two shipped gates without writing down what it broke is how a green merge produces a red suite\n" % A)
    raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
if rec.get("card") != "t116":
    sys.stderr.write("ac4 RED: the record does not belong to card t116\n"); raise SystemExit(1)
if rec.get("applied_by") != "orchestrator" or rec.get("card_writes_index_bytes") is not False:
    sys.stderr.write("ac4 RED: the record must declare applied_by=orchestrator and card_writes_index_bytes=false - the index is orchestrator-owned and t116 writes README bytes only\n"); raise SystemExit(1)
if rec.get("status") not in ("proposed", "ratified"):
    sys.stderr.write("ac4 RED: the record must be labelled proposed (or ratified once the orchestrator rules)\n"); raise SystemExit(1)
if rec.get("policy") != "W2 eight-property index-amendment policy (WAL 1248), invoked IN WRITING":
    sys.stderr.write("ac4 RED: the record must state IN WRITING that the W2 eight-property policy is invoked - this amendment changes index bytes and cannot be implicit\n"); raise SystemExit(1)
if rec.get("re_premise_not_relax") is not True:
    sys.stderr.write("ac4 RED: the record must declare re_premise_not_relax true - legs 256/258 are re-premised to the Part-2 reality, never relaxed or deleted\n"); raise SystemExit(1)
if rec.get("requirement_authority") != "REQ-DOC-010 (README under 500 lines)":
    sys.stderr.write("ac4 RED: the record must name REQ-DOC-010 as the authority it stays inside - the amendment raises a card-era budget, never a requirement\n"); raise SystemExit(1)
if rec.get("fallback_requiring_operator_ruling") != "relocating Part 2 to docs/reviewer-guide.md":
    sys.stderr.write("ac4 RED: the record must state that relocating Part 2 to a separate reviewer guide is a fallback that needs a NEW operator ruling, so no builder or verifier treats it as an available workaround\n"); raise SystemExit(1)
if rec.get("heading_count_after") != 18:
    sys.stderr.write("ac4 RED: the record must state heading_count_after = 18\n"); raise SystemExit(1)
if rec.get("new_heading") != "Reviewer / agent scoring map":
    sys.stderr.write("ac4 RED: the record must name the new level-2 heading verbatim\n"); raise SystemExit(1)
am = rec.get("amendments")
if not isinstance(am, list) or not am:
    sys.stderr.write("ac4 RED: the record must carry the concrete amendments (the new ceiling and the new heading count), not just a list of broken legs\n"); raise SystemExit(1)
amap = {int(e["index"]): e for e in am}
if set(amap) != {256, 258}:
    sys.stderr.write("ac4 RED: the record carries amendments for %s, not exactly {256, 258}\n" % sorted(amap)); raise SystemExit(1)
new_ceil = rec.get("proposed_ceiling")
measured = rec.get("measured_readme_lines")
if not isinstance(new_ceil, int) or not isinstance(measured, int):
    sys.stderr.write("ac4 RED: the record must carry the MEASURED candidate line count and the proposed ceiling as integers - a band raised by feel is not an amendment, it is a wish\n"); raise SystemExit(1)
if not (measured <= new_ceil < 500):
    sys.stderr.write("ac4 RED: proposed ceiling %s is not between the measured %d and REQ-DOC-010's 500 - the band must clear the measured count with headroom and must stay strictly inside the requirement ceiling, because the requirement is the authority and the 400 band is only a budget\n" % (new_ceil, measured)); raise SystemExit(1)
nc = rec.get("negative_control_matrix", [])
if len(nc) < 4:
    sys.stderr.write("ac4 RED: the record needs at least four negative-control legs, found %d\n" % len(nc)); raise SystemExit(1)
badnc = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
if badnc:
    sys.stderr.write("ac4 RED: negative-control legs not as expected: %s\n" % badnc); raise SystemExit(1)
PH = ["<MEASURED_README_LINES_AT_BUILD>"]
unresolved = [p for p in PH if any(p in json.dumps(e.get("replaced_regions", [])) for e in am)]
if unresolved:
    sys.stderr.write("ac4 RED: the record still carries unresolved placeholders %s - the builder must substitute its OWN measured line count into measured_readme_lines (the ceiling is byte-frozen); this fence re-verifies by reconstruction\n" % unresolved); raise SystemExit(1)
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
def get_leg(n):
    return idx[str(n)] if isinstance(idx, dict) else idx[n]
def esha(t):
    return hashlib.sha256(json.dumps(t, separators=(",", ":")).encode("utf-8")).hexdigest()
def apply_regions(src, pairs, direction, leg):
    out = src
    for r in pairs:
        needle = r["from"] if direction == "forward" else r["to"]
        repl = r["to"] if direction == "forward" else r["from"]
        if out.count(needle) != 1:
            sys.stderr.write("ac4 RED: a replaced_region %s text is not unique in the shipped leg %s command - the record does not describe the shipped bytes\n" % ("from" if direction == "forward" else "to", leg)); raise SystemExit(1)
        out = out.replace(needle, repl, 1)
    return out
states = []
for leg in ("256", "258"):
    e = amap[int(leg)]
    t = get_leg(int(leg))
    cmd = t["command"]
    cmd_sha = hashlib.sha256(cmd.encode("utf-8")).hexdigest()
    entry_sha = esha(t)
    regions = e.get("replaced_regions", [])
    if not regions:
        sys.stderr.write("ac4 RED: leg %s carries no replaced_regions - the edit must be reconstructible byte-for-byte\n" % leg); raise SystemExit(1)
    if cmd_sha == e["old_command_sha256"]:
        if entry_sha != e.get("entry_sha_before"):
            sys.stderr.write("ac4 RED: the index still holds the OLD leg %s command but the entry sha moved - the entry was edited outside the record\n" % leg); raise SystemExit(1)
        built = apply_regions(cmd, regions, "forward", leg)
        if hashlib.sha256(built.encode("utf-8")).hexdigest() != e.get("new_command_sha256"):
            sys.stderr.write("ac4 RED: applying leg %s replaced_regions forward does not reproduce new_command_sha256 - the record does not describe the intended edit\n" % leg); raise SystemExit(1)
        if apply_regions(built, regions, "reverse", leg) != cmd:
            sys.stderr.write("ac4 RED: reversing leg %s replaced_regions out of the built command does not reproduce the shipped command - the record is not lossless\n" % leg); raise SystemExit(1)
        states.append("pre-amendment")
    elif cmd_sha == e["new_command_sha256"]:
        if entry_sha != e.get("entry_sha_after"):
            sys.stderr.write("ac4 RED: the index holds the SETTLED leg %s command but not the recorded entry sha - the amended entry drifted from the record\n" % leg); raise SystemExit(1)
        if apply_regions(cmd, regions, "reverse", leg) == cmd:
            sys.stderr.write("ac4 RED: reversing leg %s replaced_regions out of the SETTLED command changed nothing - the record does not describe the shipped bytes\n" % leg); raise SystemExit(1)
        states.append("post-amendment")
    else:
        sys.stderr.write("ac4 RED: the shipped leg %s command sha %s matches NEITHER old_command_sha256 nor new_command_sha256 - the index drifted under the amendment; STOP and request a re-groom\n" % (leg, cmd_sha[:16])); raise SystemExit(1)
    if "460" not in json.dumps(regions):
        sys.stderr.write("ac4 RED: leg %s's amended text does not carry the 460 ceiling\n" % leg); raise SystemExit(1)
if len(set(states)) != 1:
    sys.stderr.write("ac4 RED: legs 256 and 258 are in DIFFERENT amendment states (%s) - a half-applied index is exactly the merge-window failure this record exists to prevent\n" % states); raise SystemExit(1)
sys.stdout.write("ac4 evidence: byte proofs - both legs reconstruct forward AND reverse losslessly in the %s state; entry shas match the record\n" % states[0])
sys.stdout.write("ac4 GREEN: BAND AMENDMENT PROPOSED IN WRITING AND BYTE-PROVEN - %s prices legs 256 and 258 against the shipped index in the %s state, invokes the W2 eight-property policy in writing, carries the measured %d lines, a proposed ceiling of %d (strictly inside REQ-DOC-010's 500), heading_count_after 18 with the new heading named, a %d-leg negative-control matrix, and records that the reviewer-guide fallback needs an operator ruling; the card itself writes zero index bytes\n" % (A, states[0], measured, new_ceil, len(nc)))
PYEOF

verification_commands.ac5:
set -u
test -f README.md || { echo "ac5 RED: README.md missing"; exit 1; }
test -f backend/scripts/docs_verification.py || { echo "ac5 RED: backend/scripts/docs_verification.py missing"; exit 1; }
